// ballerinax/aws.s3:4.0.0

# Configuration for the AWS S3 Client.
public type ConnectionConfig record {|
    # Authentication configuration
    auth:AuthConfig auth; // Special Agent Note: AuthConfig FROM ballerinax/aws.auth module
    # The AWS Region. If you don't specify an AWS region, Client uses US East (N. Virginia) as default region
    aws:Region|string region = aws:US_EAST_1; // Special Agent Note: Region FROM ballerinax/aws module
    # Optional endpoint configuration for FIPS, dualstack, or custom endpoint overrides (e.g., LocalStack)
    aws:EndpointConfig endpoint?; // Special Agent Note: EndpointConfig FROM ballerinax/aws module
|};

# Configuration for uploading an object.
public type PutObjectConfig record {|
    # The MIME type of the content
    string contentType?;
    # Specifies accessibility for this object (e.g., "private", "public-read")
    CannedACL acl = PRIVATE;
    # The Storage class of the object (e.g., "STANDARD", "GLACIER" for archive, "INTELLIGENT_TIERING")
    StorageClass storageClass = STANDARD;
    # Custom data to attach to the object (e.g., {"author": "John", "project": "demo"})
    map<string> metadata?;
    # Specifies caching behavior along the request/reply chain
    string cacheControl?;
    # Specifies presentational information for the object
    string contentDisposition?;
    # Specifies what content encodings have been applied to the object and thus what decoding mechanisms must be applied to obtain the media-type referenced by the Content-Type header field
    string contentEncoding?;
    # The language the content is in (e.g., "en-US", "fr")
    string contentLanguage?;
    # The date and time at which the object is no longer cacheable
    string expires?;
    # Tags for the object
    string tagging?;
    # Encryption type ("AES256" or "aws:kms")
    string serverSideEncryption?;
    # The file format to use for serializing record content. Overrides the format inferred from the object key extension
    FileFormat fileFormat?;
|};

# Represents the content types supported for uploading an S3 object.
public type UploadContent byte[]|string|json|xml|record {}|record {}[]|stream<byte[], error?>|stream<record {}, error?>;

# Configuration for creating presigned URLs.
public type PresignedUrlConfig record {|
    # Specifies how long the URL is valid in minutes (default: 15, max: 10080 for 7 days)
    int expirationMinutes = 15;
    # Specifies what action the URL allows ("GET" to download, "PUT" to upload)
    HttpMethod httpMethod = GET;
    # The MIME type of the content (for PUT requests)
    string contentType?;
    # Specifies presentational information for the object (for GET requests)
    string contentDisposition?;
    # Override file type when downloading (for GET requests)
    string responseContentType?;
    # Get URL for a specific version of the object (when versioning is enabled)
    string versionId?;
|};

// ballerinax/aws.auth:1.0.1

# Represents static AWS credentials.
public type StaticAuthConfig record {|
    # AWS access key ID
    string accessKeyId;
    # AWS secret access key
    string secretAccessKey;
    # AWS session token, required only for temporary credentials
    string sessionToken?;
|};

// ballerina/mime:2.12.2

# Represents values in `Content-Disposition` header.
public class ContentDisposition {
    # Default filename for storing the body part if the receiving agent wishes to store it in an external
    # file
    public string fileName = "";
    # Indicates how the body part should be presented (`inline`, `attachment`, or as `form-data`)
    public string disposition = "";
    # Represents the field name in case of `multipart/form-data`
    public string name = "";
    # A set of parameters specified in the `attribute=value` notation
    public map<string> parameters = {};

    # Converts the `ContentDisposition` type to a string suitable to use as the value of a corresponding MIME header.
    # ```ballerina
    # string contDisposition = contentDisposition.toString();
    # ```
    # + return - The `string` representation of the `ContentDisposition` object
    isolated function toString() returns string;
}
